import { Tabs } from 'expo-router';
import React from 'react';
import { Platform } from 'react-native';
import { HapticTab } from '../../components/HapticTab';
import { Ionicons, FontAwesome5, MaterialCommunityIcons } from '@expo/vector-icons';

export default function TabLayout() {
  return (
    <Tabs
      screenOptions={{
        tabBarActiveTintColor: '#f59e0b', // amber-500
        tabBarInactiveTintColor: '#9ca3af', // gray-400
        tabBarStyle: {
          backgroundColor: '#1f2937', // gray-800
          borderTopColor: '#374151', // gray-700
          borderTopWidth: 1,
          height: 60,
          paddingBottom: Platform.OS === 'ios' ? 20 : 10,
          paddingTop: 10,
        },
        tabBarLabelStyle: {
          fontSize: 12,
          fontWeight: '600',
        },
        headerShown: false,
        tabBarButton: HapticTab,
      }}>
      <Tabs.Screen
        name="index"
        options={{
          title: 'Home',
          tabBarIcon: ({ color, focused }) => (
            <Ionicons name={focused ? 'home' : 'home-outline'} size={24} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="audio"
        options={{
          title: 'Audio',
          tabBarIcon: ({ color, focused }) => (
            <Ionicons name={focused ? 'headset' : 'headset-outline'} size={24} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="scriptures"
        options={{
          title: 'Scriptures',
          tabBarIcon: ({ color, focused }) => (
            <FontAwesome5 name="book" size={20} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="stories"
        options={{
          title: 'Stories',
          tabBarIcon: ({ color, focused }) => (
            <MaterialCommunityIcons name="script-text-outline" size={24} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="pooja"
        options={{
          title: 'Pooja Room',
          tabBarIcon: ({ color, focused }) => (
            <MaterialCommunityIcons name={focused ? 'candle' : 'candle'} size={24} color={color} />
          ),
        }}
      />
    </Tabs>
  );
}

import { Tabs } from 'expo-router';
import React from 'react';
import { Platform } from 'react-native';
import { HapticTab } from '../../components/HapticTab';
import { Ionicons, FontAwesome5, MaterialCommunityIcons } from '@expo/vector-icons';

export default function TabLayout() {
  return (
    <Tabs
      screenOptions={{
        tabBarActiveTintColor: '#f59e0b', // amber-500
        tabBarInactiveTintColor: '#9ca3af', // gray-400
        tabBarStyle: {
          backgroundColor: '#1f2937', // gray-800
          borderTopColor: '#374151', // gray-700
          borderTopWidth: 1,
          height: 60,
          paddingBottom: Platform.OS === 'ios' ? 20 : 10,
          paddingTop: 10,
        },
        tabBarLabelStyle: {
          fontSize: 12,
          fontWeight: '600',
        },
        headerShown: false,
        tabBarButton: HapticTab,
      }}>
      <Tabs.Screen
        name="home"
        options={{
          title: 'Home',
          href: '/screens/HomeScreen',
          tabBarIcon: ({ color, focused }) => (
            <Ionicons name={focused ? 'home' : 'home-outline'} size={24} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="audio"
        options={{
          title: 'Audio',
          href: '/screens/audio/audio-player',
          tabBarIcon: ({ color, focused }) => (
            <Ionicons name={focused ? 'headset' : 'headset-outline'} size={24} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="scriptures"
        options={{
          title: 'Scriptures',
          href: '/screens/ScripturesScreen',
          tabBarIcon: ({ color, focused }) => (
            <FontAwesome5 name="book" size={20} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="stories"
        options={{
          title: 'Stories',
          href: '/screens/StoryScreen',
          tabBarIcon: ({ color, focused }) => (
            <MaterialCommunityIcons name="script-text-outline" size={24} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="pooja"
        options={{
          title: 'Pooja Room',
          href: '/screens/PoojaRoomScreen',
          tabBarIcon: ({ color, focused }) => (
            <MaterialCommunityIcons name="candle" size={24} color={color} />
          ),
        }}
      />
    </Tabs>
  );
}

import React from 'react';
import { View, Text, StyleSheet, TouchableOpacity } from 'react-native';
import { useRouter } from 'expo-router';
import { Ionicons } from '@expo/vector-icons';
import { SafeAreaView } from 'react-native-safe-area-context';

export default function AudioTab() {
  const router = useRouter();

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.content}>
        <Text style={styles.title}>Audio Section</Text>

        <TouchableOpacity
          style={styles.button}
          onPress={() => router.push('/screens/audio/audio-player')}
        >
          <Ionicons name="play-circle" size={24} color="white" />
          <Text style={styles.buttonText}>Audio Player</Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={styles.button}
          onPress={() => router.push('/screens/audio/audio-menu')}
        >
          <Ionicons name="list" size={24} color="white" />
          <Text style={styles.buttonText}>Audio Menu</Text>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#1f2937',
  },
  content: {
    flex: 1,
    padding: 20,
    alignItems: 'center',
    justifyContent: 'center',
  },
  title: {
    fontSize: 28,
    fontWeight: 'bold',
    color: '#f59e0b',
    marginBottom: 40,
  },
  button: {
    backgroundColor: '#374151',
    paddingVertical: 16,
    paddingHorizontal: 32,
    borderRadius: 12,
    marginBottom: 16,
    flexDirection: 'row',
    alignItems: 'center',
    width: '80%',
    justifyContent: 'center',
    borderWidth: 2,
    borderColor: '#f59e0b',
  },
  buttonText: {
    color: 'white',
    fontSize: 18,
    fontWeight: '600',
    marginLeft: 12,
  },
});

import { FontAwesome5, Ionicons, MaterialCommunityIcons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { Dimensions, Image, ImageBackground, TouchableOpacity as RNTouchableOpacity, ScrollView, StyleSheet, Text, View } from 'react-native';
import { Images, BhagwanScroller } from '../data';

// Custom TouchableOpacity with default activeOpacity
const TouchableOpacity = (props: any) => (
  <RNTouchableOpacity activeOpacity={0.7} {...props} />
);

export default function HomeTab() {
  const router = useRouter();

  return (
   <ImageBackground
    source={Images["ramSita_1"]}
    style={styles.backgroundImage}
    resizeMode="cover"
  >
    <ScrollView contentContainerStyle={styles.overlayContainer}>
      <View style={styles.innerContainer}>
        {/* Top Avatars */}
        <View style={styles.avatarRow}>
          {BhagwanScroller.map((name, idx) => (
            <Image
              key={idx}
              source={Images[name]}
              style={styles.avatar}
            />
          ))}
        </View>

        {/* Title */}
        <Text style={styles.title}>Bhakti Path</Text>

        {/* Buttons */}
        <TouchableOpacity
          style={[styles.button, { marginBottom: 12 }]}
          onPress={() => router.push('/(tabs)/audio')}
        >
          <Ionicons name="headset" size={24} color="white" />
          <Text style={styles.buttonText}>Audio</Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={[styles.button, { marginBottom: 12 }]}
          onPress={() => router.push('/(tabs)/scriptures')}
        >
          <FontAwesome5 name="book" size={24} color="white" />
          <Text style={styles.buttonText}>Scripture Reader</Text>
        </TouchableOpacity>

        <TouchableOpacity
          style={[styles.button, { marginBottom: 24 }]}
          onPress={() => router.push('/(tabs)/stories')}
        >
          <MaterialCommunityIcons name="script-text-outline" size={24} color="white" />
          <Text style={styles.buttonText}>Stories</Text>
        </TouchableOpacity>

        <TouchableOpacity
            style={[styles.button, { marginBottom: 24 }]}
            onPress={() => router.push('/(tabs)/pooja')}
        >
          <MaterialCommunityIcons name="candle" size={24} color="white" />
          <Text style={styles.buttonText}>Virtual Pooja Room</Text>
        </TouchableOpacity>
      </View>

      {/* Floating Microphone Button */}
      <TouchableOpacity
        style={styles.micButton}
        onPress={() => console.log('Voice Input Coming Soon!')}
      >
        <Ionicons name="mic" size={24} color="white" />
      </TouchableOpacity>
    </ScrollView>
  </ImageBackground>
  );
}

const styles = StyleSheet.create({
  backgroundImage: {
    flex: 1,
    width: '100%',
    height: '100%',
  },
  overlayContainer: {
    flexGrow: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.6)',
    padding: 16,
  },
  innerContainer: {
    alignItems: 'center',
    paddingTop: 40,
  },
  avatarRow: {
    flexDirection: 'row',
    marginBottom: 20,
    justifyContent: 'center',
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
    borderWidth: 2,
    borderColor: '#f59e42',
    marginHorizontal: 6,
  },
  title: {
    fontSize: 30,
    fontWeight: 'bold',
    color: '#fde68a',
    marginBottom: 20,
  },
  button: {
    backgroundColor: 'rgba(139, 69, 19, 0.8)',
    paddingVertical: 16,
    paddingHorizontal: 32,
    borderRadius: 12,
    marginBottom: 16,
    flexDirection: 'row',
    alignItems: 'center',
    width: '80%',
    justifyContent: 'center',
    borderWidth: 2,
    borderColor: '#f59e42',
  },
  buttonText: {
    color: 'white',
    fontSize: 18,
    fontWeight: '600',
    marginLeft: 12,
  },
  micButton: {
    position: 'absolute',
    bottom: 30,
    right: 30,
    backgroundColor: '#f59e0b',
    width: 60,
    height: 60,
    borderRadius: 30,
    justifyContent: 'center',
    alignItems: 'center',
    elevation: 5,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 4,
